const procedures = new Map([
  ["tasks.count", async (input) => input.titles.length],
]);

async function handle(frame) {
  const procedure = procedures.get(frame.procedure);
  if (!procedure) return { id: frame.id, success: false, error: "not found" };
  const result = await procedure(frame.payload);
  return { id: frame.id, success: true, result };
}

console.log(await handle({ id: "r1", procedure: "tasks.count", payload: { titles: ["a", "b"] } })); // { id: 'r1', success: true, result: 2 }
console.log(await handle({ id: "r2", procedure: "tasks.delete", payload: {} })); // { id: 'r2', success: false, error: 'not found' }

