function waits(delay, failures, backoff) {
  const out = [];
  for (let attempt = 1; attempt <= failures; attempt++) {
    out.push(backoff === "exponential" ? delay * 2 ** (attempt - 1) : delay * attempt);
  }
  return out;
}

console.log(waits(100, 3, "exponential"));
console.log(waits(100, 3, "linear"));

