import { createRPCMemoryTransport, createRPCProcedure, RPCClient, RPCServer } from "@zudojs/rpc";

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const server = new RPCServer();
server.register(createRPCProcedure("tasks.report", async (_input, context) => {
  for (let step = 1; step <= 5; step += 1) {
    await sleep(50);
    if (context.signal.aborted) return console.log(`stopped at step ${step}`);
  }
  console.log("ran all 5 steps");
}));

for (const transport of [createRPCMemoryTransport(server), { send: (request) => server.handle(request) }]) {
  try {
    await new RPCClient(transport).call("tasks.report", {}, { timeout: 75 });
  } catch (error) {
    console.log(error.code);
  }
  await sleep(300);
}
